function toggles(){
  document.querySelectorAll('.shelfpick').forEach(function(p){
    if(p.nextElementSibling&&p.nextElementSibling.classList.contains('nbmetog')) return;
    var b=document.createElement('button'); b.type='button'; b.className='nbmetog'; b.textContent='NBME-tested';
    b.setAttribute('aria-pressed','false'); b.title='Show only briefs linked to an NBME question'; p.after(b);
  });
  document.addEventListener('click',function(e){
    var t=e.target.closest&&e.target.closest('.nbmetog'); if(!t) return;
    window.AX_NBME_ONLY=!window.AX_NBME_ONLY;
    document.querySelectorAll('.nbmetog').forEach(function(x){ x.classList.toggle('on',!!window.AX_NBME_ONLY); x.setAttribute('aria-pressed',window.AX_NBME_ONLY?'true':'false'); });
    if(window.axApplyShelf) window.axApplyShelf();
  });
}
